-- Phone correction history: exact Direct Ready / per-phone return edits, no batch-quantity edits.
DO $grade_audit_install$ BEGIN EXECUTE $ddl$
do $$begin if public.get_imei_correction_sources_version()is distinct from '20261114-imei-correction-sources-1'then raise exception 'Verify Correction History Sources first.';end if;if to_regprocedure('public.get_imei_grade_audit_version()')is not null then if public.get_imei_grade_audit_version()is distinct from '20261114-imei-grade-audit-1'then raise exception 'Existing Grade Audit integrity needs review.';end if;end if;end;$$;
do $patch$declare sig text;old text;before_hash text;t record;c record;begin
 foreach sig in array array['greenloop_private.itc_history(uuid,integer,integer)','greenloop_private.itc_enrich(jsonb,uuid,uuid)']loop
 old:=pg_get_functiondef(sig::regprocedure);before_hash:=md5(old);
 if sig like '%itc_history%'then execute $history$
create or replace function greenloop_private.itc_history(dev uuid,p_offset integer,p_limit integer)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 with access as materialized(select coalesce(public.get_my_partner_name_access(),false)names,coalesce(public.has_page_capability_v1('parts','view'),false)prices),audits as materialized(
 select 'data:'||h.id id,h.changed_at at,h.changed_by actor,h.change_reason reason,
 greenloop_private.itc_changes(coalesce((select jsonb_object_agg(key,value->'old')from jsonb_each(case when jsonb_typeof(h.changed_fields)='object'then h.changed_fields else '{}'::jsonb end)where jsonb_typeof(value)='object'),'{}'),coalesce((select jsonb_object_agg(key,value->'new')from jsonb_each(case when jsonb_typeof(h.changed_fields)='object'then h.changed_fields else '{}'::jsonb end)where jsonb_typeof(value)='object'),'{}'),'IMEI details',a.names,a.prices)changes
 from public.data_change_history h cross join access a where h.device_id=dev and not(h.changed_fields?'full_workflow'and exists(select 1 from greenloop_private.workflow_correction_audit w where w.device_id=dev and position(w.id::text in(h.changed_fields->'full_workflow'->>'new'))>0))
 union all
 select 'workflow:'||w.id,w.changed_at,w.actor,w.reason,coalesce((select jsonb_agg(c order by n,c->>'key')from jsonb_array_elements(w.changes)with ordinality z(x,n)cross join lateral jsonb_array_elements(greenloop_private.itc_changes(greenloop_private.wf_public_values(x->>'kind',x->'before',a.prices),greenloop_private.wf_public_values(x->>'kind',x->'after',a.prices),initcap(replace(x->>'kind','_',' ')),a.names,a.prices))c),'[]')
 from greenloop_private.workflow_correction_audit w cross join access a where w.device_id=dev
 union all
 select 'bulk:'||b.request_id,b.changed_at,b.actor,b.reason,greenloop_private.itc_changes(greenloop_private.itc_bulk_values(x->'before'),greenloop_private.itc_bulk_values(x->'after'),'Bulk IMEI Correction',a.names,a.prices)
 from greenloop_private.bulk_imei_audit b cross join access a cross join lateral jsonb_array_elements(b.changes)x where x->>'device_id'=dev::text
 union all
 select 'chaman:'||h.id,h.created_at,h.actor,h.reason,greenloop_private.itc_changes(jsonb_build_object('transfer_date',h.before_data->'document'->'created_at','transfer_notes',h.before_data->'document'->'notes','included_in_transfer',true,'shop_received_at',l->'shop_received_at','company_received_at',l->'company_received_at','phase',l->'phase','voided_at',l->'voided_at'),jsonb_build_object('transfer_date',h.after_data->'document'->'created_at','transfer_notes',h.after_data->'document'->'notes','included_in_transfer',after_line is not null,'shop_received_at',after_line->'shop_received_at','company_received_at',after_line->'company_received_at','phase',after_line->'phase','voided_at',after_line->'voided_at'),'Chaman Transfer Correction',a.names,a.prices)
 from greenloop_private.chaman_audit h cross join access a cross join lateral jsonb_array_elements(h.before_data->'lines')l left join lateral(select x after_line from jsonb_array_elements(coalesce(h.after_data->'lines','[]'))x where x->>'id'=l->>'id'limit 1)newline on true where l->>'device_id'=dev::text
 union all
 select 'event:'||e.id,e.created_at,e.actor_id,coalesce(e.event_data->>'reason',e.event_title),greenloop_private.itc_changes(greenloop_private.itc_bulk_values(e.event_data->'before'),greenloop_private.itc_bulk_values(e.event_data->'after'),'Saved correction event',a.names,a.prices)
 from public.device_events e cross join access a where e.device_id=dev and e.event_type~'(^|_)(corrected|correction)$'and jsonb_typeof(e.event_data->'before')='object'and jsonb_typeof(e.event_data->'after')='object'
 and not exists(select 1 from public.data_change_history h where h.device_id=dev and h.id::text=coalesce(e.event_data->>'audit_id',e.event_data->>'change_id',e.event_data->>'history_id'))
 and not exists(select 1 from greenloop_private.workflow_stage_audit w where w.device_id=dev and w.request_id::text=e.event_data->>'audit_id'and w.command->>'action'='edit'and w.command->>'kind'in('direct_ready','supplier_return'))
 and not exists(select 1 from greenloop_private.workflow_correction_audit h where h.device_id=dev and h.id::text=e.event_data->>'audit_id')
 and not exists(select 1 from greenloop_private.bulk_imei_audit h cross join lateral jsonb_array_elements(h.changes)x where h.request_id::text=e.event_data->>'audit_id'and x->>'device_id'=dev::text)
 union all
 select 'stage:'||w.request_id,w.changed_at,w.actor,w.reason,greenloop_private.itc_changes(
 case when w.command->>'kind'='direct_ready'then jsonb_build_object('final_grade',w.before_data->'final_grade','final_battery_health',w.before_data->'battery_health')else jsonb_build_object('reason',w.before_data->'reason','notes',w.before_data->'notes')end,
 case when w.command->>'kind'='direct_ready'then jsonb_build_object('final_grade',w.after_data->'final_grade','final_battery_health',w.after_data->'battery_health')else jsonb_build_object('reason',w.after_data->'reason','notes',w.after_data->'notes')end,
 case when w.command->>'kind'='direct_ready'then 'Ready Stock outcome'else 'Supplier Return'end,a.names,a.prices)
 from greenloop_private.workflow_stage_audit w cross join access a where w.device_id=dev and w.command->>'action'='edit'and w.command->>'kind'in('direct_ready','supplier_return')
 ),shaped as materialized(select a.id,a.at occurred_at,coalesce(u.full_name,'Recorded user')actor,a.reason,case split_part(a.id,':',1)when 'bulk'then 'Bulk IMEI Correction'when 'workflow'then 'IMEI Workflow Correction'when 'data'then 'IMEI Data Correction'when 'stage'then 'IMEI Data Correction'when 'chaman'then 'Chaman Transfer Correction'else 'Saved correction event'end source,a.changes from audits a left join public.user_profiles u on u.id=a.actor),payload as(select coalesce(jsonb_agg(to_jsonb(s)order by occurred_at desc,id),'[]')all_rows from shaped s)
 select jsonb_build_object('version','20261114-imei-qc-corrections-1','sources_version','20261114-imei-correction-sources-1','grade_audit_version','20261114-imei-grade-audit-1','offset',p_offset,'limit',p_limit,'total',jsonb_array_length(all_rows),'snapshot',md5(all_rows::text),'rows',coalesce((select jsonb_agg(x order by n)from jsonb_array_elements(all_rows)with ordinality z(x,n)where n>p_offset and n<=p_offset+p_limit),'[]'))from payload;
$$;
$history$;
 else execute $enrich$
create or replace function greenloop_private.itc_enrich(data jsonb,dev uuid,latest_job uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare d public.devices%rowtype;j public.jobs%rowtype;q record;begin
 select *into d from public.devices where id=dev and deleted_at is null;if d.id is null then return data;end if;select *into j from public.jobs where id=latest_job and device_id=dev and deleted_at is null;
 select *into q from(select f.final_grade grade,f.final_battery_health bh,f.final_battery_health_unavailable unavailable,f.inspected_at at,'Final QC / B-DEPT'::text source from public.final_qc_inspections f where f.job_id=j.id and f.device_id=dev and not(coalesce(f.routed_to_frame,false)and position('Initial QC direct route to Frame'in coalesce(f.notes,''))>0)
 union all select x.final_grade,x.battery_health,x.battery_health_unavailable,x.ready_at,'Initial QC direct Ready release'from greenloop_private.qc_direct_ready x where x.job_id=j.id and x.device_id=dev)f order by at desc,source limit 1;
 data:=jsonb_set(data,'{rows}',coalesce((select jsonb_agg(r||jsonb_build_object('report_correction',r->>'stage'='correction'or r->>'status'='admin_correction'or exists(select 1 from public.device_events e where e.device_id=dev and r->>'id'='event:'||e.id and e.event_type~'(^|_)(corrected|correction)$'))order by n)from jsonb_array_elements(data->'rows')with ordinality x(r,n)),'[]'));
 -- These edit paths have an immutable stage audit but no mirrored device event.
 data:=jsonb_set(data,'{rows}',coalesce(data->'rows','[]')||coalesce((select jsonb_agg(jsonb_build_object('id','report-stage:'||w.request_id,'occurred_at',w.changed_at,'stage','correction','title','Reports correction','actor',coalesce(u.full_name,'Recorded user'),'status','admin_correction','report_correction',true,'details',jsonb_build_array(jsonb_build_object('label','Reason','value',w.reason)))order by w.changed_at,w.request_id)from greenloop_private.workflow_stage_audit w left join public.user_profiles u on u.id=w.actor where w.device_id=dev and w.command->>'action'='edit'and w.command->>'kind'in('direct_ready','supplier_return')and not exists(select 1 from public.device_events e where e.device_id=dev and e.event_data->>'audit_id'=w.request_id::text)),'[]'));
 return jsonb_set(data,'{device}',data->'device'||jsonb_build_object('initial_battery_health',d.battery_health,'initial_battery_health_unavailable',d.battery_health_unavailable,'supplier_grade',coalesce(nullif(j.supplier_grade,''),d.original_grade),'gl_grade',d.gc_grade,'final_battery_health',q.bh,'final_battery_health_unavailable',q.unavailable,'final_grade',q.grade,'final_qc_source',q.source))||jsonb_build_object('qc_details_version','20261114-imei-qc-corrections-1','report_corrections',greenloop_private.itc_history(dev,0,50));
end;$$;
$enrich$;end if;
 -- Reseal only receipts whose existing reviewed before-hash matches.
 for c in select *from(values('identity','hash'),('identity','before_hash'),('identity','definition_hash'),('object_identity','definition_hash'),('function_identity','definition_hash'))x(idcol,hashcol)loop
  for t in select cls.oid::regclass::text name from pg_class cls where cls.relnamespace='greenloop_private'::regnamespace and cls.relkind='r'and cls.relname like '%_installation'and exists(select 1 from pg_attribute where attrelid=cls.oid and attname=c.idcol and atttypid='text'::regtype)and exists(select 1 from pg_attribute where attrelid=cls.oid and attname=c.hashcol and atttypid='text'::regtype)loop
   execute format('update %s set %I=md5(pg_get_functiondef(to_regprocedure($1)))where replace(%I,'' '','''')=replace($1,'' '','''')and %I=$2',t.name,c.hashcol,c.idcol,c.hashcol)using sig,before_hash;
  end loop;
 end loop;
 update greenloop_private.office_routines set original_hash=md5(pg_get_functiondef(sig::regprocedure))where to_regprocedure(implementation)=sig::regprocedure and original_hash=before_hash;
 update greenloop_private.capability_routines set original_hash=md5(pg_get_functiondef(sig::regprocedure))where to_regprocedure(implementation)=sig::regprocedure and original_hash=before_hash;
 end loop;end;$patch$;
revoke all on function greenloop_private.itc_history(uuid,integer,integer),greenloop_private.itc_enrich(jsonb,uuid,uuid)from public,anon,authenticated;
insert into greenloop_private.capability_rpc_rules values('get_imei_grade_audit_version','{"read":true}')on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
create table if not exists greenloop_private.imei_grade_audit_installation(identity text primary key,hash text not null);alter table greenloop_private.imei_grade_audit_installation enable row level security;revoke all on greenloop_private.imei_grade_audit_installation from public,anon,authenticated;
create or replace function public.get_imei_grade_audit_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_imei_correction_sources_version()='20261114-imei-correction-sources-1'and(select count(*)=3 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.imei_grade_audit_installation)and not exists(select 1 from pg_proc where pronamespace='greenloop_private'::regnamespace and proname in('itc_history','itc_enrich')and(has_function_privilege('anon',oid,'EXECUTE')or has_function_privilege('authenticated',oid,'EXECUTE')))and exists(select 1 from pg_class where oid='greenloop_private.imei_grade_audit_installation'::regclass and relrowsecurity)and not has_table_privilege('authenticated','greenloop_private.imei_grade_audit_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')then '20261114-imei-grade-audit-1'end;$$;
revoke all on function public.get_imei_grade_audit_version()from public;grant execute on function public.get_imei_grade_audit_version()to anon,authenticated;
insert into greenloop_private.imei_grade_audit_installation select sig,md5(pg_get_functiondef(sig::regprocedure))from unnest(array['greenloop_private.itc_history(uuid,integer,integer)','greenloop_private.itc_enrich(jsonb,uuid,uuid)','public.get_imei_grade_audit_version()'])sig on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_imei_grade_audit_version()is distinct from '20261114-imei-grade-audit-1'then raise exception 'IMEI Grade Audit verification failed. Nothing installed.';end if;end;$$;
notify pgrst,'reload schema';
$ddl$;END;$grade_audit_install$;
select public.get_imei_grade_audit_version()as installed_imei_grade_audit_version;
